  srs: ['https://en.wikipedia.org/wiki/Spaced_repetition', 'Wikipedia — Spaced repetition', 'Wikipedia — Lặp lại ngắt quãng'],
  anki: ['https://ankiweb.net/', 'AnkiWeb — flashcards with spaced repetition', 'AnkiWeb — thẻ ghi nhớ lặp lại ngắt quãng'],
  num: ['https://en.wikipedia.org/wiki/Chinese_numerals', 'Wikipedia — Chinese numerals', 'Wikipedia — Chữ số tiếng Trung'],
